describe('Notification Filtering', () => {
    beforeEach(() => {
        cy.visit('/notifications');
    });

    it('should filter notifications by type - info', () => {
        cy.get('[data-testid="filter-info"]').click();
        cy.get('[data-testid="notification"]').each(($el) => {
            cy.wrap($el).should('have.class', 'info');
        });
    });

    it('should display no notifications when filtering by a non-existent type', () => {
        cy.get('[data-testid="filter-nonexistent"]').click();
        cy.get('[data-testid="notification"]').should('have.length', 0);
    });
});
